## Algorithm: a token bucket in a Redis Lua script

Each client gets a bucket that refills at `rate` tokens per second up to a cap of `burst`, and each request spends one token. This allows normal bursts but caps the sustained rate. Running it as a Lua script keeps the read-refill-write step atomic across all workers, in one round trip. The script uses Redis's `TIME`, not `Date.now()`, so clock differences between boxes don't matter.

```js
// ratelimit.js (sketch)
const { client } = require("./redis");

const PLANS = {
  free: { rate: 5,  burst: 20 },   // placeholder numbers; set them from real traffic
  pro:  { rate: 50, burst: 200 },
};

client.defineCommand("takeToken", {
  numberOfKeys: 1,
  lua: `
    local rate, burst = tonumber(ARGV[1]), tonumber(ARGV[2])
    local t = redis.call("TIME")
    local now = t[1] * 1000 + math.floor(t[2] / 1000)
    local b = redis.call("HMGET", KEYS[1], "tokens", "ts")
    local tokens = tonumber(b[1]) or burst
    local ts = tonumber(b[2]) or now
    tokens = math.min(burst, tokens + (now - ts) / 1000 * rate)
    local allowed = 0
    if tokens >= 1 then tokens = tokens - 1; allowed = 1 end
    redis.call("HSET", KEYS[1], "tokens", tokens, "ts", now)
    redis.call("PEXPIRE", KEYS[1], math.ceil(burst / rate * 1000))
    return { allowed, math.ceil(math.max(0, 1 - tokens) / rate * 1000) }
  `,
});

async function rateLimit(req, res, next) {
  const { rate, burst } = PLANS[req.client.plan] || PLANS.free;
  let allowed, retryMs;
  try {
    [allowed, retryMs] = await client.takeToken(`rl:${req.client.client_id}`, rate, burst);
  } catch (err) {
    return next(); // fail open: a Redis problem shouldn't turn into a 429 for everyone
  }
  if (!allowed) {
    res.set("Retry-After", String(Math.ceil(retryMs / 1000)));
    return res.status(429).json({ error: "rate_limited" });
  }
  next();
}

module.exports = { rateLimit };
```

To wire it in, add `router.use(rateLimit)` in `routes/api.js` directly after the auth middleware (after line 19). It needs `req.client`, so it can't run earlier.

