  const key = req.get("Idempotency-Key");
  if (!key || key.length > 255) {
    return res.status(400).json({ error: "Idempotency-Key header required" });
  }

  const row = await db.write(
    `INSERT INTO orders (account_id, sku, quantity, idempotency_key)
     VALUES ($1, $2, $3, $4)
     ON CONFLICT (account_id, idempotency_key)
       DO UPDATE SET idempotency_key = EXCLUDED.idempotency_key
     RETURNING *, (xmax = 0) AS inserted`,
    [req.user.accountId, req.body.sku, req.body.quantity, key]
  );

  if (!row.inserted &&
      (row.sku !== req.body.sku || row.quantity !== Number(req.body.quantity))) {
    return res.status(422).json({ error: "Idempotency-Key reused with a different payload" });
  }

  const { inserted, ...order } = row;
  res.status(201).set("Idempotent-Replayed", String(!inserted)).json(order);
});
```

