async function load() {
  clearTimeout(timer);
  try {
    const res = await fetch('/api/metrics');
    const { rows, computed_at, next_at, server_now } = await res.json();
    render(rows);
    stamp(computed_at);
    const skew = Date.now() - Date.parse(server_now);
    const delay = Date.parse(next_at) + skew - Date.now() + 3000 + Math.random() * 2000;
    timer = setTimeout(load, Math.max(delay, 5000));
  } catch { timer = setTimeout(load, backoff()); }
}
document.addEventListener('visibilitychange', () =>
  document.hidden ? clearTimeout(timer) : load());
```

**Cost**: 1 request/min per open tab × 4KB/30ms. Negligible.

**Optional**: replace `no-store` with a short edge cache (`s-maxage` = seconds until next rollup) so many viewers share one DB read. Risk: if the job runs late, the edge serves stale data. With ETag/304 it's probably not needed.

